-- Тема 08: уточнения по проверке Codex (29 исправлений в 16 вопросах), ключи не меняются.
-- Источник: scripts/questions/083_codex_topic08_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'Почему работа с временными таблицами быстрее, чем с обычными?', NULL, NULL, NULL, 'Что снижает накладные расходы при работе с временными таблицами?'),
        ('question', 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны?', NULL, NULL, NULL, 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны без пользовательской автоматизации?'),
        ('question', 'Столбец допускает NULL. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', NULL, NULL, NULL, 'Столбец допускает NULL, ограничение UNIQUE задано по одному столбцу. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?'),
        ('option', 'Для чего нужен шаблон template0?', 'Для восстановления pg_dump и другой кодировки', 'Для чистой базы без изменений template1', 'Чистый шаблон, в котором нет изменений template1: из него создают базу для восстановления из pg_dump и базу с другой кодировкой.', 'Из template0 создают чистую базу для восстановления дампа или базу с кодировкой, отличной от template1.'),
        ('option', 'С объектами каких баз может работать клиент в рамках одного подключения?', 'Любых баз кластера', 'Любых баз этого кластера сразу', 'Подключение всегда к одной базе.', NULL),
        ('option', 'С объектами каких баз может работать клиент в рамках одного подключения?', 'Той базы, к которой подключён, во всех схемах', 'Подключённой базы, в доступных ему схемах', 'Для другой базы нужно новое подключение.', 'Для другой базы нужно новое подключение; доступ к объектам схем определяется привилегиями.'),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Схемы из search_path слева направо', 'По фактическому пути поиска слева направо', 'Используется первая одноимённая таблица в фактическом пути поиска, включая неявно добавленные схемы. Для перегруженных функций правило сложнее: учитываются и типы аргументов.', 'Используется первая одноимённая таблица в фактическом пути поиска, включая неявно добавленные схемы pg_temp и pg_catalog. Для перегруженных функций правило сложнее: учитываются и типы аргументов.'),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Используется схема public по умолчанию', 'По порядку схем, отсортированных по имени', 'public используется, если она есть в пути поиска; сам путь определяет порядок.', 'Порядок определяется путём поиска, а не сортировкой имён схем.'),
        ('option', 'Как PostgreSQL находит таблицу, указанную без имени схемы?', 'Используется схема pg_catalog первой', 'В pg_catalog; если таблицы нет — ошибка', 'Если pg_catalog нет в пути, она неявно просматривается перед ним; поиск идёт по всему пути.', 'pg_catalog просматривается неявно, но поиск идёт по всему пути, а не завершается ошибкой после неё.'),
        ('option', 'В какую схему попадёт новая постоянная таблица, созданная без указания схемы?', 'В первую подходящую схему пути поиска', 'В первую существующую схему с USAGE в search_path', 'В первую существующую и доступную схему из явно указанных в пути поиска: нужно право CREATE в этой схеме.', 'Рассматриваются явно указанные элементы пути. Отсутствие CREATE в выбранной схеме вызывает ошибку; следующая схема не подбирается.'),
        ('option', 'Что происходит с временной схемой pg_temp_N по окончании сеанса?', 'Объекты удаляются, схема остаётся другим', 'Объекты удаляются, сама схема сохраняется', 'Объекты удаляются, а сама схема остаётся и достаётся другим сеансам.', NULL),
        ('option', 'Что снижает накладные расходы при работе с временными таблицами?', 'Хранятся в кеше ОС, а не на диске', NULL, 'Временные таблицы хранятся в файлах, а не в кеше ОС.', 'Временные таблицы имеют файловое хранение. Их страницы могут кешироваться ОС; внутри PostgreSQL используются локальные буферы сеанса.'),
        ('option', 'Что снижает накладные расходы при работе с временными таблицами?', 'Не журналируются и не идут через общий буферный кеш', 'Данные не пишутся в WAL и используют локальный кеш', 'Данные временной таблицы не журналируются и обрабатываются в локальном буферном кеше сеанса, а не в общем.', NULL),
        ('option', 'Что снижает накладные расходы при работе с временными таблицами?', 'Их данные сжимаются при каждой записи', NULL, 'Сжимаются длинные значения через TOAST, как и в обычных таблицах.', 'TOAST может сжимать подходящие значения при необходимости; это не обязательное сжатие при каждой записи.'),
        ('option', 'Что изменилось для схемы public начиная с PostgreSQL 15?', 'Начальные права доступа к ней были ограничены', 'У PUBLIC отозвано право CREATE по умолчанию', 'Раньше создавать в ней объекты мог любой пользователь.', 'Раньше при стандартных правах создавать в ней объекты мог любой пользователь; с PostgreSQL 15 право CREATE у PUBLIC отозвано по умолчанию.'),
        ('option', 'Есть автоматически обновляемое представление CREATE VIEW active_users AS SELECT id, active FROM users WHERE active; Выполняют DELETE FROM active_users WHERE id = 7; Видимая строка с id = 7 существует, права есть, мешающих ограничений и триггеров нет. Что удалится?', 'Все строки users независимо от условия', 'Строки users за пределами условия представления', 'Учитываются условие представления и условие DELETE.', NULL),
        ('option', 'Чем материализованное представление отличается от обычного представления?', 'Может существовать в памяти клиентского приложения', 'Создаётся как объект клиентского приложения', 'Это объект базы данных на сервере.', 'Клиент может хранить копию прочитанного результата, но само материализованное представление — объект серверной базы.'),
        ('option', 'Как заново вычислить и сохранить данные существующего материализованного представления monthly_sales?', '`ANALYZE MATERIALIZED VIEW monthly_sales;`', '`ANALYZE (VERBOSE, SKIP_LOCKED) monthly_sales;`', 'ANALYZE собирает статистику для планировщика, а не пересчитывает результат запроса.', NULL),
        ('option', 'Как заново вычислить и сохранить данные существующего материализованного представления monthly_sales?', '`REINDEX TABLE monthly_sales CONCURRENTLY;`', '`REINDEX TABLE CONCURRENTLY monthly_sales;`', 'REINDEX перестраивает индексы, а не данные определяющего запроса.', NULL),
        ('option', 'Какие утверждения о материализованном представлении в PostgreSQL 16 верны без пользовательской автоматизации?', 'Сохранённый результат совпадает с исходными таблицами', 'Индекс на представлении поддерживает его актуальность', 'Актуальность зависит от момента обновления.', 'Индекс ускоряет доступ к сохранённым строкам, но не обновляет результат по изменениям исходных таблиц.'),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'Чужой nextval не изменяет наш currval', 'Чужой nextval не меняет currval нашего сеанса', 'currval привязан к последнему nextval именно в текущем сеансе.', NULL),
        ('option', 'В сеансе не вызывают setval. Какие утверждения о currval для конкретной последовательности верны?', 'currval вычисляет MAX(id) таблицы последовательности', 'currval вычисляет MAX(id) связанной таблицы', 'Он не сканирует таблицу и не вычисляет максимальный идентификатор.', 'currval возвращает сохранённое значение сеанса, не вычисляя максимум в пользовательской таблице.'),
        ('option', 'Что обеспечивает PRIMARY KEY для столбца или группы столбцов таблицы?', 'Уникальность значений и запрет NULL в каждом столбце ключа', 'Уникальность ключа и NOT NULL его столбцов', 'Первичный ключ позволяет однозначно идентифицировать строку.', 'У составного ключа уникальна комбинация значений; NULL запрещён в каждом столбце. Первичный ключ позволяет однозначно идентифицировать строку.'),
        ('option', 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', 'Да: CHECK не нарушается при выражении NULL', 'Да: CHECK допускает результат выражения NULL', 'CHECK (price > 0) сам по себе допускает NULL; чтобы запретить NULL, рекомендуется добавить NOT NULL.', NULL),
        ('option', 'На price задано только CHECK (price > 0), ограничения NOT NULL нет. Допустима ли вставка NULL?', 'Нет: любое ограничение CHECK запрещает NULL', NULL, 'CHECK и NOT NULL — разные проверки.', 'CHECK и NOT NULL — разные проверки: CHECK (price IS NOT NULL) мог бы запретить NULL, а данный CHECK (price > 0) допускает его.'),
        ('option', 'Столбец допускает NULL, ограничение UNIQUE задано по одному столбцу. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'UNIQUE допускает любые повторяющиеся ненулевые значения', 'UNIQUE допускает повторяющиеся ненулевые значения', 'Повторяющиеся ненулевые ключи нарушают уникальность.', NULL),
        ('option', 'Столбец допускает NULL, ограничение UNIQUE задано по одному столбцу. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'Поведение NULL в UNIQUE меняется настройкой сервера', 'Равенство NULL в UNIQUE задаётся в postgresql.conf', 'NULLS NOT DISTINCT указывается для конкретного ограничения или уникального индекса.', 'Режим задаётся NULLS DISTINCT или NULLS NOT DISTINCT в определении ограничения либо уникального индекса; общего параметра конфигурации для этого нет.'),
        ('option', 'Столбец допускает NULL, ограничение UNIQUE задано по одному столбцу. Какие утверждения об ограничении UNIQUE в PostgreSQL 16 верны?', 'Любое UNIQUE автоматически добавляет NOT NULL', 'UNIQUE автоматически добавляет NOT NULL', 'Автоматический запрет NULL относится к PRIMARY KEY, а не к любому UNIQUE.', NULL),
        ('option', 'Внешний ключ объявлен DEFERRABLE INITIALLY DEFERRED. Чем в этом случае ON DELETE RESTRICT отличается от ON DELETE NO ACTION?', 'NO ACTION можно отложить, RESTRICT нельзя', 'Проверка NO ACTION отложима, RESTRICT — нет', 'При INITIALLY DEFERRED проверка NO ACTION по умолчанию ждёт COMMIT; SET CONSTRAINTS ... IMMEDIATE может вызвать её раньше. RESTRICT не откладывается даже у отложенного ключа: он срабатывает сразу, в момент команды.', 'При INITIALLY DEFERRED проверка NO ACTION по умолчанию ждёт COMMIT; SET CONSTRAINTS ... IMMEDIATE может вызвать её раньше. Проверка RESTRICT выполняется в рамках текущей команды и не переносится на COMMIT.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
